// L alerte doit se lire d un coup d oeil sur un telephone.
//
// ELLE GROUPE PAR MARCHAND, pas par type. Quand une chaine casse, elle casse
// pour UNE boutique : l exploitant a besoin de savoir chez qui aller, pas
// combien d anomalies existent au total.
const r = $input.first().json || {};
const anomalies = r.anomalies || [];

const LIBELLES = {
  confirmee_sans_livreur: 'Confirmee, aucun livreur lance',
  livree_sans_frais:      'Livree sans frais annonces',
  livree_sans_decompte:   'Livree sans decompte de stock',
  panier_oublie:          'Panier oublie en collecte',
  forfait_depasse:        'Forfait de commandes depasse',
  whatsapp_marchand:      'Session WhatsApp du marchand deconnectee',
  'compte-wasender':      'Compte wasender en cause — abonnement ou limite',
  'ligne-whatsapp-eteinte': 'Ligne WhatsApp payee mais deconnectee',
};

const parBoutique = {};
for (const a of anomalies) {
  const b = a.boutique || 'boutique inconnue';
  (parBoutique[b] = parBoutique[b] || []).push(a);
}

const lignes = [];
for (const [boutique, liste] of Object.entries(parBoutique)) {
  lignes.push('');
  lignes.push('*' + boutique + '*');
  for (const a of liste) {
    lignes.push('  • ' + (LIBELLES[a.type] || a.type));
    lignes.push('    ' + a.reference + ' — ' + a.detail);
  }
}

const titre = anomalies.length === 1
  ? 'CHAINE ROMPUE'
  : 'CHAINES ROMPUES (' + anomalies.length + ')';

return [{ json: { message: '🔗 ' + titre + lignes.join('\n') } }];

